-- Numeric primary keys (id_<entity>) without losing data.
--
-- Hand-written (drizzle-kit would drop and recreate the columns): every table
-- is transformed in place, and drizzle's migrator runs it in one transaction,
-- so any failed check below rolls the whole migration back.
--
-- Nothing is deleted:
--   * the old uuid PK column `id` is renamed to `uuid` (still unique): the
--     offline idempotency key on sales / workers / audit_events;
--   * every old uuid FK column is renamed to `legacy_<col>_uuid` (nullable,
--     no constraint) and dropped later by 0009, once nothing reads it.
-- Existing rows are numbered oldest first (created_at).
-- Rollback: drizzle/rollback/0008_down.sql.

-- Fail fast instead of queueing behind (or blocking) the app, and never hold
-- the locks if the client connection drops mid-migration.
SET LOCAL lock_timeout = '10s';--> statement-breakpoint
SET LOCAL idle_in_transaction_session_timeout = '15s';--> statement-breakpoint

