-- 4. Guard: a nullable FK that had a value must have resolved to one. (The
--    NOT NULL ones are already guarded by SET NOT NULL above.) Any miss
--    aborts the whole migration.
DO $$
DECLARE
  misses integer;
BEGIN
  SELECT
      (SELECT count(*) FROM "workers" WHERE "legacy_registered_by_uuid" IS NOT NULL AND "registered_by" IS NULL)
    + (SELECT count(*) FROM "workers" WHERE "legacy_approved_by_uuid" IS NOT NULL AND "approved_by" IS NULL)
    + (SELECT count(*) FROM "discount_policies" WHERE "legacy_created_by_uuid" IS NOT NULL AND "created_by" IS NULL)
    + (SELECT count(*) FROM "sales" WHERE "legacy_courtesy_approved_by_uuid" IS NOT NULL AND "courtesy_approved_by" IS NULL)
    + (SELECT count(*) FROM "sales" WHERE "legacy_worker_id_uuid" IS NOT NULL AND "id_worker" IS NULL)
    + (SELECT count(*) FROM "sales" WHERE "legacy_policy_id_uuid" IS NOT NULL AND "id_policy" IS NULL)
    + (SELECT count(*) FROM "stock_movements" WHERE "legacy_actor_id_uuid" IS NOT NULL AND "id_actor" IS NULL)
    + (SELECT count(*) FROM "loyalty_ledger" WHERE "legacy_sale_id_uuid" IS NOT NULL AND "id_sale" IS NULL)
    + (SELECT count(*) FROM "audit_events" WHERE "legacy_actor_id_uuid" IS NOT NULL AND "id_actor" IS NULL)
    + (SELECT count(*) FROM "audit_events" WHERE "legacy_worker_id_uuid" IS NOT NULL AND "id_worker" IS NULL)
  INTO misses;
  IF misses > 0 THEN
    RAISE EXCEPTION '0008_numeric_ids: % foreign key value(s) did not resolve', misses;
  END IF;
END $$;--> statement-breakpoint

